.main_slider .slide {
  display: inline-block !important;
  width: 400px;
  margin-right: 20px;
}

/* SLIDER ANIMATION */
selector .slick-track {
  gap: 0 !important;
}

/* Left to Right Animation */
#ltr_slide .slick-slider {
  width: auto !important;
  padding: 0 !important;
}

#ltr_slide .slick-list.draggable {
  overflow: hidden !important;
}

#ltr_slide .slick-track {
  transition-timing-function: linear !important;
}

#ltr_slide .slick-track {
  display: flex;
  animation: ltrSlide 150s linear infinite;
}

@keyframes ltrSlide {
  from {
    transform: translateX(-50%);
  }
  to {
    transform: translateX(0);
  }
}

/* Right to Left Animation */
#rtl_slide .slick-slider {
  width: auto !important;
  padding: 0 !important;
}

#rtl_slide .slick-list.draggable {
  overflow: hidden !important;
}

#rtl_slide .slick-track {
  transition-timing-function: linear !important;
}

#rtl_slide .slick-track {
  display: flex;
  animation: rtlSlide 150s linear infinite;
}

@keyframes rtlSlide {
  from {
    transform: translateX(0);
  }
  to {
    transform: translateX(-50%);
  }
}

